// === Tab: mySketch ===
let particles = [];

function setup() {
  createCanvas(920, 690);
	colorMode(HSB, 255);

  for (let i = 0; i < 100; i++) {
    let p = {
      x: random(width),
      y: random(height),
      vx: random(-1, 1),
      vy: random(-1, 1),
      c: color(random(255), 255, 255, 100)
    };
    particles.push(p);
  }
}

function draw() {
  background(20, 20, 30, 25); // 半透明の背景で残像効果を演出

  // パーティクルを描画し、動きを与える
  for (let i = 0; i < particles.length; i++) {
    var p = particles[i];

    // 他のパーティクルとの相互作用
    for (let j = 0; j < particles.length; j++) {
      if (i !== j) {
        let other = particles[j];
        let d = dist(p.x, p.y, other.x, other.y);
        if (d < 200) {
          stroke(j*2.5, 255, 255, 100); // 2つの色をブレンド
          line(p.x, p.y, other.x, other.y); // パーティクル間に線を引く
        }
      }
    }

    // パーティクルの動き
    p.x += p.vx;
    p.y += p.vy;

    // 画面端で反射させる
    if (p.x < 0 || p.x > width) p.vx *= -1;
    if (p.y < 0 || p.y > height) p.vy *= -1;
  }
}

function mouseClicked(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

